-- JOB PUBLISHING ENGINE (2026-10-13): publish one job to many portals from one screen, through a database queue
-- and a separate worker process (backend/src/workers/postingWorker.js). See docs/job-publishing/.
-- ADDITIVE ONLY: five new tables, nothing existing is touched. (RequirementPosting, the by-hand tasks, the feeds
-- and the careers page are NOT changed; the engine writes its outcome back to RequirementPosting through utils.)
--   PostingQueue      one row per publish / republish / unpublish / update / credential check. Atomic claim,
--                     retry with backoff, dead letters, idempotency key (unique), schedule (scheduledFor).
--   PostingLog        the step-by-step log of every run (never a secret), with an optional screenshot file.
--   PortalCredential  the company's login for a portal. username / password / secret are AES-256-GCM ciphertext
--                     (utils/secrets.js, INTEGRATION_SECRET_KEY). "enabled" is the per-portal switch, default OFF.
--   PortalMapping     ATS value -> the portal's own word / code (employment type, experience, salary, city, industry).
--   PortalPosting     one row per (job, portal): the portal-side status of the job (DRAFT QUEUED PUBLISHED FAILED
--                     NEEDS_CHECK UNPUBLISHED EXPIRED), its portal job id and URL.
-- DateTime columns hold epoch milliseconds (the same as every Prisma SQLite DateTime). The application reads and
-- writes these tables with plain SQL, so it works before or after prisma generate.
-- Undo: rollback.sql.
CREATE TABLE "PostingQueue" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "requirementId" TEXT,
    "portal" TEXT NOT NULL,
    "action" TEXT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'QUEUED',
    "attempts" INTEGER NOT NULL DEFAULT 0,
    "maxAttempts" INTEGER NOT NULL DEFAULT 3,
    "nextRunAt" DATETIME NOT NULL DEFAULT 0,
    "scheduledFor" DATETIME,
    "lockedBy" TEXT,
    "lockedAt" DATETIME,
    "startedAt" DATETIME,
    "finishedAt" DATETIME,
    "payloadHash" TEXT,
    "idempotencyKey" TEXT NOT NULL,
    "dryRun" INTEGER NOT NULL DEFAULT 0,
    "batchId" TEXT,
    "requestedBy" TEXT,
    "requestedByName" TEXT,
    "errorCode" TEXT,
    "errorMessage" TEXT,
    "retryable" INTEGER NOT NULL DEFAULT 0,
    "resultJson" TEXT,
    "createdBy" TEXT,
    "updatedBy" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT 0,
    "updatedAt" DATETIME NOT NULL DEFAULT 0,
    CONSTRAINT "PostingQueue_requirementId_fkey" FOREIGN KEY ("requirementId") REFERENCES "Requirement" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE UNIQUE INDEX "PostingQueue_idempotencyKey_key" ON "PostingQueue"("idempotencyKey");
CREATE INDEX "PostingQueue_status_nextRunAt_idx" ON "PostingQueue"("status", "nextRunAt");
CREATE INDEX "PostingQueue_portal_status_idx" ON "PostingQueue"("portal", "status");
CREATE INDEX "PostingQueue_requirementId_portal_idx" ON "PostingQueue"("requirementId", "portal");
CREATE INDEX "PostingQueue_batchId_idx" ON "PostingQueue"("batchId");
CREATE INDEX "PostingQueue_createdAt_idx" ON "PostingQueue"("createdAt");

CREATE TABLE "PostingLog" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "queueId" TEXT,
    "requirementId" TEXT,
    "portal" TEXT NOT NULL,
    "step" TEXT NOT NULL,
    "level" TEXT NOT NULL DEFAULT 'INFO',
    "message" TEXT NOT NULL,
    "screenshotPath" TEXT,
    "durationMs" INTEGER,
    "createdAt" DATETIME NOT NULL DEFAULT 0,
    CONSTRAINT "PostingLog_queueId_fkey" FOREIGN KEY ("queueId") REFERENCES "PostingQueue" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "PostingLog_requirementId_fkey" FOREIGN KEY ("requirementId") REFERENCES "Requirement" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE INDEX "PostingLog_queueId_createdAt_idx" ON "PostingLog"("queueId", "createdAt");
CREATE INDEX "PostingLog_requirementId_createdAt_idx" ON "PostingLog"("requirementId", "createdAt");
CREATE INDEX "PostingLog_portal_createdAt_idx" ON "PostingLog"("portal", "createdAt");

CREATE TABLE "PortalCredential" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "portal" TEXT NOT NULL,
    "accountLabel" TEXT NOT NULL DEFAULT 'default',
    "usernameEnc" TEXT,
    "passwordEnc" TEXT,
    "secretEnc" TEXT,
    "status" TEXT NOT NULL DEFAULT 'UNVERIFIED',
    "lastVerifiedAt" DATETIME,
    "lastError" TEXT,
    "enabled" INTEGER NOT NULL DEFAULT 0,
    "dailyLimit" INTEGER,
    "hourlyLimit" INTEGER,
    "minGapSeconds" INTEGER,
    "createdBy" TEXT,
    "updatedBy" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT 0,
    "updatedAt" DATETIME NOT NULL DEFAULT 0
);
CREATE UNIQUE INDEX "PortalCredential_portal_accountLabel_key" ON "PortalCredential"("portal", "accountLabel");

CREATE TABLE "PortalMapping" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "portal" TEXT NOT NULL,
    "field" TEXT NOT NULL,
    "atsValue" TEXT NOT NULL,
    "portalValue" TEXT NOT NULL,
    "portalCode" TEXT,
    "sortOrder" INTEGER NOT NULL DEFAULT 0,
    "active" INTEGER NOT NULL DEFAULT 1,
    "origin" TEXT NOT NULL DEFAULT 'default',
    "createdBy" TEXT,
    "updatedBy" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT 0,
    "updatedAt" DATETIME NOT NULL DEFAULT 0
);
CREATE UNIQUE INDEX "PortalMapping_portal_field_atsValue_key" ON "PortalMapping"("portal", "field", "atsValue");
CREATE INDEX "PortalMapping_portal_field_idx" ON "PortalMapping"("portal", "field");

CREATE TABLE "PortalPosting" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "requirementId" TEXT NOT NULL,
    "portal" TEXT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'DRAFT',
    "portalJobId" TEXT,
    "portalUrl" TEXT,
    "publishedAt" DATETIME,
    "expiresAt" DATETIME,
    "autoRepublish" INTEGER NOT NULL DEFAULT 0,
    "lastError" TEXT,
    "lastQueueId" TEXT,
    "lastAction" TEXT,
    "payloadHash" TEXT,
    "verifiedAt" DATETIME,
    "createdBy" TEXT,
    "updatedBy" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT 0,
    "updatedAt" DATETIME NOT NULL DEFAULT 0,
    CONSTRAINT "PortalPosting_requirementId_fkey" FOREIGN KEY ("requirementId") REFERENCES "Requirement" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE UNIQUE INDEX "PortalPosting_requirementId_portal_key" ON "PortalPosting"("requirementId", "portal");
CREATE INDEX "PortalPosting_portal_status_idx" ON "PortalPosting"("portal", "status");
CREATE INDEX "PortalPosting_expiresAt_idx" ON "PortalPosting"("expiresAt");

